#!/usr/bin/env bash
# ============================================================================
# TEST INVENTORY DRIFT — is docs/test-inventory.json still true?
# ============================================================================
# docs/test-inventory.json is generated by scripts/ci_test_inventory.py and
# committed. Nothing regenerated it, so it described 163 files and 1,131 tests
# while the tree had 173 files and the suite ran 4,835 tests (audit 2026-10-24).
# A committed artifact that no gate reads is a claim with an expiry date nobody
# watches — the same class as the README badges.
#
# This gate regenerates into a temp copy and compares. It never leaves the
# working tree modified: the original file is restored on every exit path.
#
# Usage: scripts/check_test_inventory.sh
# Exit: 0 current · 1 stale (prints the diff) · 2 cannot run
# ============================================================================
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

INVENTORY="docs/test-inventory.json"
GENERATOR="scripts/ci_test_inventory.py"

[[ -f $INVENTORY ]] || { printf '::error::falta %s\n' "$INVENTORY" >&2; exit 2; }
[[ -f $GENERATOR ]] || { printf '::error::falta %s\n' "$GENERATOR" >&2; exit 2; }

BACKUP="$(mktemp)"
trap 'cp "$BACKUP" "$INVENTORY" 2>/dev/null || true; rm -f "$BACKUP"' EXIT

cp "$INVENTORY" "$BACKUP"

python3 "$GENERATOR" >/dev/null || {
  printf '::error::%s no pudo ejecutarse\n' "$GENERATOR" >&2
  exit 2
}

if cmp -s "$BACKUP" "$INVENTORY"; then
  printf 'OK: %s está al día con el árbol.\n' "$INVENTORY"
  exit 0
fi

printf '::error::%s está desactualizado: regeneralo con python3 %s y commiteá el resultado.\n' \
  "$INVENTORY" "$GENERATOR" >&2
diff -u "$BACKUP" "$INVENTORY" | head -n 40 >&2 || true
exit 1
